"use strict";(globalThis.webpackChunkztools_docs=globalThis.webpackChunkztools_docs||[]).push([[41914],{51764(e){e.exports=JSON.parse('{"id":"callvault","name":"CallVault","url":"https://callvault.aoneahsan.com","platforms":["Android"],"logo":"/ecosystem/callvault.svg","card":"Meeting notes cover the meeting. CallVault keeps the phone call that came before it.","title":"CallVault: a record of the calls you would otherwise take notes on","intro":"CallVault records calls on Android through the audio source your phone makes available. Its library on the phone lets you play a call back, search it, add notes and export it.","sections":[["How does it fit next to ZTools\u2019 meeting notes?","The ZTools meeting notes generator turns a meeting into notes you can use. Plenty of decisions happen on a phone call instead. CallVault keeps that call, so you can find the detail later and write it up."],["Where are the recordings kept?","On your phone. They leave it only if you turn on private cloud backup."],["What can I do with a recording?","Play it back, search the library, attach notes and export it."]]}')}}]);